# Replace the Q9 entries of /output/report.json by the revised set (window-integrated, unmasked ratios; beam test; ladder N/S forward model; RADEX; contamination). Idempotent.
import json
P='/output/report.json'; r=json.load(open(P))
r['results']=[x for x in r['results'] if 'Q9' not in x.get('evidence','')]
r['recipe']=[s for s in r['recipe'] if not s['description'].startswith('Q9')]
if '\n\nQ9 (velocity-resolved' in r['interpretation']: r['interpretation']=r['interpretation'].split('\n\nQ9 (velocity-resolved')[0]
r['caveats']=[c for c in r['caveats'] if not c.startswith('Q9')]
A=[{"name":"convention","value":"Jy-flux ratio HCN/HCO+ 3-2 of velocity-window-integrated fluxes at a common circular beam (Tb ratio = x1.0126), velocity relative to VSYS=2780 km/s (radio, LSRK), |v| windows 0-60, 60-100, 100-150, 150-250, 100-260 km/s, blue (-) and red (+) separately and stacked; NO S/N clipping; error = random-position x line-free-window null (MAD) added in quadrature to the linear-baseline-fit variance; HCN-only detection -> lower limit, HCO+-only -> upper limit (2-sigma, (A-2eA)/(B+2eB)); detections defined at 3 sigma in the window"},
   {"name":"centres","value":"HCO+ +-350 km/s peak at the working beam near N (0,+2.55\") and S (-0.15,-2.55\"), Bridge (0.3,0.15\"); HCN peak coincides within 0.0\" (N) and 0.047\" (S, one pixel)"}]
def add(q,v,u,c,ev,t,unit="ratio",extra=None):
    r['results'].append({"quantity":q,"value":v,"uncertainty":u,"unit":unit,"assumptions":A+(extra or []),"confidence":c,"evidence":ev+" | Q9","target":t})
SYS="stat from nulls; array-recovery term on Xb4b-vs-Xb4d ratios: measured 0.5-2% in cores (same aperture/beam: 0.765 vs 0.769, 0.675 vs 0.689), <=20% (within 1.2 sigma) in the wings; adopt 5% scale systematic"
add("HCN/HCO+ 3-2 across the line profile at the N nucleus, window-integrated, unmasked (Xb4b @0.30\", r<0.25\"; Xb4d @1.05\", r<0.5\")",
 "Xb4b 0.30\" r<0.25\": 1.04+-0.02 (-60..0), 0.95+-0.01 (0..60), 0.92+-0.02 (60..100), core |v|<60 0.982+-0.013; wings 100-150: 1.05+-0.09 (red), 1.04+-0.14 (blue); 100-260 red 1.10+-0.17, blue 0.97+-0.21, stacked 1.05+-0.13 (150-250 stacked HCN 0.049+-0.013 vs HCO+ 0.045+-0.018 Jy km/s, ratio 1.1+-0.5 unconstrained). => ratio is 0.92-1.04 across +-100 km/s (a ~12% blue-to-red decline) and ~1.05+-0.13 in the wings: no significant wing rise at 0.30\". Xb4d 1.05\" r<0.5\": core 0.769+-0.004; 60-100 0.733+-0.007 (blue)/0.900+-0.013 (red); 100-150 0.86+-0.05/1.13+-0.08; 100-260 1.05+-0.11 (blue)/1.35+-0.18 (red), stacked 1.19+-0.10 (4.2 sigma above the core 0.77); 150-250 stacked HCN 0.081+-0.011 (7 sigma) vs HCO+ 0.017+-0.016: lower limit >1.2 (2 sigma). r 0.5-1\": core 0.689, stacked 100-260 1.15+-0.11; r 1-2\": core 0.50, 1.02+-0.26. So at 1.05\" the wings reach >=1 (HCN/HCO+ 100-260 km/s = 1.19+-0.10, Tb 1.20) while the core is 0.77",
 SYS,"medium","scripts/q9b_windows.py -> out/q9b/windows.csv, windows.log","N peak (r<0.5\" and r<0.25\")")
add("Is the 1.05\" N wing rise / ratio-vs-velocity slope a beam (spatial-mixing) effect? Matched-aperture, matched-beam, centroid and injection tests",
 "Same aperture r<0.5\" about N, 40-km/s bins over +-140 km/s, no mask: weighted linear slope Xb4d@1.05\" +0.082+-0.006 per 100 km/s (chi2/dof const 221/6); Xb4b convolved to 1.05\" +0.072+-0.008 (92/6) -> the two arrays agree (difference 1.0 sigma, so not an Xb4b-recovery effect); Xb4b at native-like 0.30\" +-0.003+-0.013 (12/6, mean 0.875). Same data, same aperture, only the beam changes -> the slope is generated by the 1.05\" beam. Injection (HCN = R(r_N)*HCO+ on the Xb4b HCO+ cube, R from the measured profile 0.98/0.82/0.63/0.48/0.40 at r=0.125/0.375/0.75/1.5/3\", identical kinematics, smoothed to 1.05\"): predicted slope +0.049 per 100 km/s (mean 0.78 vs observed 0.77): i.e. ~60-70% of the observed slope arises from a purely radial ratio gradient + velocity gradient, none from spectral variation; residual +0.02-0.03 per 100 km/s (3 sigma) is not reproduced (steeper unresolved central R(r) or genuine red-wing HCN excess). Centroids (HCN minus HCO+ per 40 km/s bin, r<1.2\", Xb4d): dx = +0.04..+0.06\" (blue), -0.001 (0), -0.09 (+80), -0.125+-0.034\" (+120 km/s); Xb4b 0.30\": +0.02 -> -0.038+-0.003\" (+80); dy <=0.04\": HCN emission is systematically closer to the nucleus than HCO+ at every velocity (HCO+ centroid moves -0.5\" -> +0.28\" across the line), with a larger offset on the red side, consistent with an HCN-richer compact core mixed in a 1.05\" beam with lower-ratio extended gas",
 "slopes +-0.006-0.013; centroid errors from S/N (0.6 FWHM/SNR) + no systematic astrometry; injection input R(r) measured at 0.30\" so central gradient underestimated","medium","scripts/q9b_beam.py -> out/q9b/beam.log, beam_slopes.csv, centroids.csv, injection.csv","N, 1.05\" vs 0.30\"",unit="per 100 km/s")
add("HCN/HCO+ 3-2 across the line profile at S and Bridge, window-integrated, unmasked (Xb4d @1.05\", Xb4b @0.30\"): is the S deficit present at all velocities?",
 "S Xb4d r<0.5\": core 0.375+-0.006, 100-150 0.40+-0.04 (red)/0.372+-0.017 (blue), 150-250 blue 0.64+-0.13, 100-260 stacked 0.443+-0.031 (r<0.5), 0.407+-0.033 (0.5-1), 0.445+-0.058 (1-2\"); per-bin slope -0.001+-0.007 per 100 km/s. S Xb4b 0.30\" r<0.25\": core 0.414+-0.014, blue 100-150 0.438+-0.021, blue 150-250 0.485+-0.127, red 100-150 HCO+ only (R<3 limit not constraining), stacked 100-260 0.443+-0.045, 150-250 stacked 0.43+-0.18 (HCO+-only, upper limit 1.3). => the S ratio stays 0.37-0.45 (HCN/HCO+, Tb x1.01) out to |v|~260 km/s, i.e. 2-3x below N at all velocities with HCN detected; a mild (~2 sigma) rise 0.375 -> 0.44 from core to wings at 1.05\" is not seen at 0.30\" (0.414 -> 0.443+-0.045). Bridge (Xb4d, r<1\"): core 0.439+-0.005; 100-150 0.93+-0.21 (red)/1.03+-0.31 (blue); 100-260 red 1.58+-0.42, blue 0.93+-0.48 (limit >0.18), stacked 1.35+-0.32 (HCN 0.336+-0.038 = 9 sigma vs HCO+ 0.248+-0.052): Bridge wings have a ratio >=1 (2.9 sigma above the core)",
 SYS+"; S red wings are HCO+-dominated and noise-limited beyond +150 km/s","medium","scripts/q9b_windows.py, q9b_beam.py -> out/q9b/windows.csv, beam_slopes.csv","S peak, Bridge")
add("4-3/3-2 per molecule across the line profile at the common 6.5\" beam, unmasked, window-integrated, and the N/S-weighted forward model (Xb47/Xb4f; weights from Xb4d 3-2 cubes at 6.5\")",
 "Unmasked Tb ratios: HCN -100..100 0.409+-0.003, -250..-100 0.40+-0.06, 100..250 0.386+-0.036; HCO+ -100..100 0.500+-0.002, -250..-100 0.504+-0.052, 100..250 0.396+-0.028 (red-wing drop 0.50 -> 0.40, 3.7 sigma). Per 40 km/s bin HCN 0.37-0.45 (core), HCO+ 0.44-0.52 (core), 0.353+-0.029 at +130. Xb4d->6.5\" weights: the HCO+ 3-2 red wing (+100..250) is only 19% N / 81% S flux (core 56% N; HCN wing 52% N), blue wing 21% N. Fit I43=I32*(R_N f_N+R_S(1-f_N)) with constant R_N,R_S (bins with 3-2 S/N>3, |v|<=250): HCN R_N=0.459+-0.010, R_S=0.303+-0.020 (chi2/dof 63/10; single R 0.407, 90/11); HCO+ R_N=0.575+-0.008, R_S=0.402+-0.009 (127/8; single R 0.498, 231/9). The model predicts HCO+ red wing 0.434 (obs 0.396+-0.028; N/S weighting explains ~2/3 of the 0.50->0.40 drop, residual 0.04+-0.03 = 1.3 sigma) and HCN wing 0.384 (obs 0.386+-0.036). So the HCO+ red-wing drop is mostly N/S weighting (red HCO+ is S-dominated, S having lower 4-3/3-2: R_S/R_N=0.70 for HCO+, 0.66 for HCN), not an intrinsic velocity effect; the fits remain statistically poor (chi2/dof 6-16) because an extended component (Xb4d recovers only 78-80% of Xb4f 3-2 at |v|<100) and sub-structure in N and S are unmodelled; a third component with free ratio gave an unphysical R_E<0 (consistent with 0) and does not fix chi2",
 "stat <=0.01 in cores, +-0.03-0.1 in wings; no flux-recovery correction (<~10% ladder systematic); model weights assume Xb4d recovers N/S compact flux fully","medium","scripts/q9b_ladder.py -> out/q9b/ladder.log, ladder_bins.csv, ladder_fit.csv","N+S merged (6.5\"), N and S components",
 extra=[{"name":"rest frequencies (GHz)","value":"HCN 3-2 265.886434, 4-3 354.505477; HCO+ 3-2 267.557626, 4-3 356.734223"}])
add("Brightness temperature per channel and RADEX consequences: N core ratio ~1 vs S 0.4 (HCN/HCO+ 3-2)",
 "Native-like peak Tb (aperture mean r<0.25\" at 0.30\"): N HCN 1.5 K, HCO+ 1.6 K (peak pixel at 0.25\": 2.63/2.82 K, Q4); S HCN 0.7 K, HCO+ 1.6 K (peak pixel 1.34/2.94 K). Per-channel Tb(HCN) = 0.972*Tb(HCO+) through the origin at N (0.30\"), 0.428 at S, 0.778/0.379 at N/S at 1.05\"; the per-channel ratio at N is 0.96 for channels above half peak, so lines do not saturate to different ceilings. RADEX grids (HCN, HCO+ LAMDA, H2, Tkin 20-300 K, n 1e3-1e8, N<=10^17.5 per 150 km/s, X=N(HCN)/N(HCO+) 0.3-10, equal filling, T_R>=observed Tb): N core ratio 0.99+-0.05 -> tau(HCN 3-2) 3-300 and tau(HCO+) 1-290 in >=95% of allowed models (X<=3.2), n>=1e6 cm-3, filling factor eta=Tb/T_R 0.02-0.35 (a 2.8 K peak against T_R of 8-150 K: strong beam dilution/clumping), 4-3/3-2 ladder 0.92 (thermalised) for both; i.e. ratio~1 is the equal-Tex optically-thick signature, independent of X for X<=3. S (0.42+-0.02): no model with both tau>3 and Tex within 10% gives 0.3-0.5 (0 of 541); allowed: HCN moderately thick (tau 0.3-30) with lower N(HCN)/N(HCO+)<=1 and n 1e5-1e8, or Tex(HCN)<Tex(HCO+) (sub-thermal, n~1e3.5-5.5 with X>=1 and ladder 0.28/0.43 -> matches the observed merged 0.41/0.50 only for that low-n branch). Wings: N 0.30\" stacked 1.06+-0.13 is allowed by the same thick solutions as the core; the 1.05\" wing value 1.20+-0.10 (Tb) is NOT reachable for X<=1 (R32 <=1.04 even at tau>>1) and needs X>=3 (HCN-enriched or HCO+ less opaque: tau(HCN) 0.7-3, tau(HCO+) 0.1-1.8 at X=3.2) or X=10 with tau(HCO+)~2",
 "grid tolerance max(1 sigma,5%); RADEX unreliable for tau>1e3 (cut); X and filling degenerate with n,T","low","scripts/q9b_radex.py, q9b_tb.py -> out/q9b/radex.log, radex_allowed.csv, radex_grid_ratios.csv, tb.log, tb_scatter.png","N, S nuclei",unit="K / ratio")
add("Line identification / contamination of the HCN and HCO+ wings (Q9 windows) and aperture-centre sensitivity",
 "Catalogue lines (out/inband_lines_curated.csv, rest-frame velocity relative to the line at VSYS=2780): HCN 3-2 red side: CH3NH2 cluster at 263.278-263.293 GHz (+144..+160 km/s, Eu 45 K, logA -5.0), CH3CHO 4(2,2)-3(0,3) +119 (logA -6.9, negligible), CH3NH2 +269; blue side: CH3NH2 -79..-118 (Eu 61-142 K, logA -5.1..-5.5), CH3CHO 6(2,4)-5(1,5) -145 (logA -4.6); HCO+ 3-2 red: CH3OH 9(0)-8(1) E at +171 (Eu 117 K, logA -4.33), CH3CHO 7(5,3)-8(4,4) +115 (logA -5.2), CH3SH +211; blue: CH3CHO 15(0,15)-14(1,14) at -186 (Eu 109 K, logA -4.04), CH3CHO vt=1 -71 (Eu 240 K). Blends with HCO+ would lower the wing ratio (so the HCN-excess lower limits are conservative); HCN-side blends cannot be excluded by the data for individual lines, but the HCN excess over HCO+ appears on BOTH sides at N (blue -250..-150 HCN 0.028+-0.008 vs HCO+ -0.001+-0.010 Jy km/s; red +150..+250 0.053+-0.008 vs 0.018+-0.012), and the red-only CH3NH2 cluster cannot produce the blue side; none of these species is individually detected in the nuclear spectra (out/blind_detections_reassigned.csv assigns only weak CH3NH2 candidates), so contamination is unquantified at the <~30% level of the 100-260 km/s HCN flux. Aperture shifts of +-0.1\" at Xb4b N (r<0.25\"): core 0.964-0.982, blue 0.944-1.032, red 0.917-0.981 (ratio changes <=0.02 core, <=0.07 wings); S core 0.403-0.428, red wing 0.26-0.51 (noise). HCN-HCO+ peak offsets: N 0.00\", S 0.047\" (one pixel) -> negligible compared to the 0.25\" aperture",
 "aperture shift +-0.02 core, +-0.07 wings; contamination not quantified","low","scripts/q9b_windows.py (centre-shift block) -> out/q9b/centre_shift.csv; out/inband_lines_curated.csv","N, S, HCN/HCO+ wings")
r['interpretation']+=("\n\nQ9 (velocity-resolved ratios, revised after review): HCN/HCO+ 3-2 is NOT strictly flat in velocity, and the supported statements are: (i) at the N nucleus at 0.30\" (r<0.25\", 50 pc) the window-integrated ratio is 0.92-1.04 across +-100 km/s (~12% blue-to-red decline) and 1.05+-0.13 in the 100-260 km/s wings (no significant rise; core 0.98+-0.013); (ii) at 1.05\" (r<0.5\") there is a significant monotonic trend, +0.08+-0.006 per 100 km/s, with the wings (100-260 km/s stacked 1.19+-0.10, lower limit >1.2 at 150-250 km/s) 4 sigma above the core (0.77); the same trend appears when Xb4b is convolved to 1.05\" (+0.072+-0.008) and vanishes at 0.30\" (-0.003+-0.013), HCN centroids lie 0.04-0.13\" closer to the nucleus than HCO+, and an injection of the measured radial ratio gradient with identical kinematics reproduces ~60-70% of the slope (+0.049): it is predominantly a beam/spatial-mixing effect with a residual (+0.02-0.03 per 100 km/s) not reproduced by the injection, which could be an HCN wing excess of a few 0.1 in the ratio from gas with a different ratio or lower HCO+ opacity; (iii) the S deficit is present at all velocities with HCN detected: 0.37-0.45 from the core to |v|~260 km/s (stacked wings 0.44+-0.03 at 1.05\", 0.44+-0.05 at 0.30\"), i.e. 2-3x below N, valid for |v|<~260 km/s where HCN is detected (HCO+-only beyond); (iv) the Bridge wing ratio rises to >=1 (1.35+-0.32 stacked 100-260 km/s vs core 0.44). "
 "Physically (RADEX with equal filling): the N core ratio ~1 with per-channel Tb(HCN)/Tb(HCO+)=0.96-0.97 over the full profile is what two optically thick (tau>~3), thermalised lines of the same Tex and width produce (ratio -> 1 for X<=3), with peak Tb of only 1.5-2.8 K implying filling factors 0.02-0.35; it does not constrain the abundance ratio X for X<=3. S (0.42) cannot be two thick equal-Tex lines: it needs lower N(HCN)/N(HCO+)<=1 with moderate HCN opacity, or Tex(HCN)<Tex(HCO+) at lower density; the fact that the S ratio is constant over the whole profile argues for a ratio set by the gas as a whole rather than by the line core saturating. An opacity-driven core dip is not seen anywhere. The 4-3/3-2 ladder (6.5\") separates N and S only through Xb4d weights: R(4-3/3-2, Tb) is 0.46 (N) vs 0.30 (S) for HCN and 0.575 vs 0.40 for HCO+, and the red-wing HCO+ drop (0.50 -> 0.40) is mostly (~2/3) N/S weighting, since red HCO+ flux is 81% S.")
r['caveats'].append("Q9 (revised): errors are statistical nulls plus baseline-fit variance; apertures about one centre are nested/correlated and bins within a profile are not fully independent (channel correlation is in the nulls). Xb4b-vs-Xb4d ratio systematic 5% (measured 0.5-2% core). Wing windows beyond +-150 km/s are noise-limited in at least one line; limits are 2-sigma. Contamination of the HCN wings by CH3NH2/CH3CHO and of HCO+ by CH3OH/CH3CHO is judged from the catalogue only (not quantified); the symmetric blue/red HCN excess at N argues against a one-sided blend. The N/S ladder forward model assumes the Xb4d compact-flux weights and constant per-nucleus R, and has chi2/dof 6-16; Xb4d recovers 78-80% of the Xb4f 3-2 flux. RADEX uses a single zone, equal filling for both lines and 150 km/s FWHM (columns scale as N/dv); results are consequences of each interpretation, not unique solutions. Previous 'flat with velocity'/'no opacity signature' wording is superseded.")
r['recipe'].append({"order":max(s['order'] for s in r['recipe'])+1,"stage":"measurement","description":"Q9: channel-resolved HCN/HCO+ 3-2 (q9_vel.py, 40-km/s bins, masked) revised in q9b: window-integrated unmasked ratios with null+baseline errors and censored limits (q9b_windows.py), beam/centroid/injection tests (q9b_beam.py), N/S forward model of the 6.5\" ladder with Xb4d weights (q9b_ladder.py), per-channel Tb and RADEX grids (q9b_tb.py, q9b_radex.py).","scripts":["scripts/q9_vel.py","scripts/q9_ladder.py","scripts/q9b_lib.py","scripts/q9b_windows.py","scripts/q9b_beam.py","scripts/q9b_ladder.py","scripts/q9b_tb.py","scripts/q9b_radex.py","scripts/build_report_q9b.py"]})
json.dump(r,open(P,'w'),indent=1)
